CREATE TABLE result AS SELECT (SELECT count(*) FROM mail WHERE rowid=15) AS c1,(SELECT count(*) FROM mail WHERE body MATCH 'sqlite') AS c2,(SELECT count(*) FROM mail WHERE mail MATCH 'search') AS c3,(SELECT count(*) FROM mail WHERE rowid BETWEEN 15 AND 20) AS c4,(SELECT count(*) FROM mail WHERE subject='database') AS c5,(SELECT count(*) FROM mail WHERE subject MATCH 'database') AS c6